//! Agent-facing documentation and harness scaffolding.
//!
//! ScratchPost is consumed by LLM coding agents, not only by humans. This module
//! owns the single authoritative description of the agent contract and renders it
//! into the file formats each harness reads. Everything here is deterministic
//! text generation: no network, no LLM, no per-workspace state.

use crate::protocol::Config;
use crate::workspace;
use std::fs;
use std::path::{Path, PathBuf};

/// Marker written into every generated file. `sp init` overwrites a file only
/// when this marker is present, so a user's hand-written `.cursorrules` is never
/// clobbered.
pub const GENERATED_MARKER: &str = "<!-- generated-by: scratchpost -->";

/// Files `sp init` writes, relative to the master root.
pub const SCAFFOLD_PATHS: &[&str] = &[
    "scratchpost-agent-prompt.md",
    "AGENT_INSTRUCTIONS.md",
    ".scratchpost/agent-instructions.md",
    ".cursorrules",
    ".github/copilot-instructions.md",
    ".claude/skills/scratchpost/SKILL.md",
    ".claude/skills/scratchpost/skill.json",
];

pub struct ScaffoldReport {
    pub written: Vec<PathBuf>,
    pub skipped: Vec<PathBuf>,
}

/// Renders the canonical agent contract. `master` is used only for the display
/// path; the content is otherwise workspace-independent so it can be committed.
pub fn render_instructions(master: &Path, config: &Config) -> String {
    let state = workspace::state_dir(master);
    let state_display = state.to_string_lossy();
    format!(
        r#"{marker}
# ScratchPost Agent Instructions

This workspace is coordinated by **ScratchPost** (`sp`). Several AI agents may be
working in it at the same time. ScratchPost gives each agent a private worktree
and a private port band, and it gates `git commit` so that two agents cannot
silently corrupt shared state.

Read this file before your first commit. It is generated by `sp init` and is
authoritative for this workspace.

## 1. You are in a session, not in the master folder

Your working directory is a session workspace, not the canonical master folder:

```
{state_display}/sessions/<agent>/workspace/
```

Every child repository there is a `git worktree` sharing one object database.
Never `cd` into the canonical master folder and never edit files there. If a
command reports `SP_PATH_OUTSIDE_SESSION`, you left the session workspace.

Your session exports these variables; use them instead of hardcoding ports:

| Variable | Meaning |
|---|---|
| `SP_AGENT` | your agent name |
| `SP_SESSION_ROOT` | your session workspace |
| `SP_PORT_BASE` | first port of your reserved band |
| `SERVER_PORT` | a port you may bind |
| `COMPOSE_PROJECT_NAME` | unique Docker Compose project name |
| `TMPDIR` | your private temporary directory |

## 2. Never commit without validating sequence rules

Liquibase `changeSet id` values and Flyway `V<version>__` filenames are **global
sequences**, not local identifiers. Two agents picking the same number produces a
repository that merges cleanly and fails at deploy time.

Before you add a migration, ask the daemon which key is free:

```sh
sp sequence next --namespace <repo>:<path-or-directory> --after <n>
```

The namespace is the repository name plus the file (Liquibase) or directory
(Flyway), for example:

```sh
sp sequence next --namespace auth-service:src/main/resources/db/dbchangelog.xml --after 199
sp sequence next --namespace billing-service:db/migration --after 41
```

Use the returned key. Do not guess, and do not reuse a key you saw in another
agent's branch.

## 3. Interpreting `SP_BLOCKED`

A blocked commit exits with status `1` and writes a deterministic report to
`stderr`. It is **not** a transient Git error and retrying unchanged will fail
again. The report has a fixed shape:

```
SP_BLOCKED v1 code=<CODE> conflict_id=<ID>
agent=<agent> repo=<repo> branch=<branch> operation=git.commit

EVIDENCE
  rule: liquibase.changeset_id
  namespace: auth-service:src/main/resources/db/dbchangelog.xml
  file: src/main/resources/db/dbchangelog.xml
  line: 8
  requested value: 200
  reserved by: agent_1 (intent/claim 1)
  lowest_free: 201
  ...

RESOLUTION
  1. ...
       <exact command>
  2. ...

RETRY CONTRACT
  mode: rerun_original_command
  ...

FORBIDDEN
  - git commit --no-verify
  ...

SP_CONFLICT_JSON={{"schema":"sp.conflict.v1", ...}}
```

The last line is the machine-readable form. Parse `SP_CONFLICT_JSON` rather than
scraping the prose: it carries `code`, `evidence`, `resolution.steps[].command`,
and `retry`.

| `code` | Meaning | Action |
|---|---|---|
| `SP_SEQUENCE_COLLISION` | another agent owns this sequence key | run the `sp resequence` command in `resolution.steps` |
| `SP_BARRIER_WAIT` | a coordination barrier is open | wait, then retry; or `sp barrier status` |
| `SP_STALE_BASE` | your branch is behind the base branch | `sp sync --rebase --agent $SP_AGENT` |
| `SP_INTENT_CONFLICT` | a peer holds a conflicting intent | inspect `sp status`, then retry |
| `SP_SESSION_NOT_ATTACHED` | your lease expired | re-attach with `sp run --agent $SP_AGENT -- <cmd>` |
| `SP_GIT_INVOCATION_REJECTED` | you bypassed the managed shim | use plain `git` from the session `PATH` |
| `SP_DAEMON_UNAVAILABLE` | `scratchpostd` is not running | `sp daemon &` |

## 4. Self-correction commands

```sh
# Reassign a duplicate sequence key and re-stage the file in one step.
sp resequence --agent "$SP_AGENT" --file <repo>/<path> --from <old> --to <new>

# Rebase your session onto the current base branch.
sp sync --rebase --agent "$SP_AGENT" [--repo <name>]

# Inspect coordination state.
sp status [--json]
sp claims [--json]
sp notices [--json]
sp barrier status
```

`sp resequence` edits the file, rewrites the key, and stages the result. After it
succeeds, re-run your original `git commit` unchanged.

## 5. Forbidden actions

- `git commit --no-verify` — the managed hook rejects it, and it defeats the gate.
- Editing anything under `{state_display}/` — that is daemon-owned state.
- Force-pushing another agent's branch.
- Committing from the canonical master folder.
- Reusing a sequence key that `sp sequence next` did not return to you.

## 6. MCP tools

If your harness speaks MCP, run `sp --mcp` and use these tools instead of shelling
out. They return the same contracts as the CLI.

| Tool | Purpose |
|---|---|
| `sp_status` | workspace health, active agents, open barriers, claims |
| `sp_claim` | reserve a path (advisory or mandatory) before staging |
| `sp_sequence_next` | lowest free sequence key in a namespace |
| `sp_resequence` | rewrite a duplicate key and stage the file |
| `sp_sync` | rebase the session onto the base branch |
| `sp_barrier_arrive` | signal completion in barrier modes |
| `sp_notices` | coordination notices after a sequence number |
| `sp_config_set` | switch coordination mode |
| `sp_evict` | evict an abandoned session |

Tool failures return `isError: true` with the same `SP_BLOCKED` payload in
`structuredContent`, so one parser handles both transports.

## 7. Current workspace configuration

| Setting | Value |
|---|---|
| coordination mode | `{mode}` |
| barrier scope | `{scope}` |
| barrier timeout | `{barrier_timeout} ms` |
| session lease | `{lease_timeout} ms` |
| port band start | `{port_base}` |
| port band width | `{port_width}` |

Change the mode with `sp config --mode <fcfs|barrier-stacked|barrier-integration>`
or from the Mission Control dashboard (`sp ui`).
"#,
        marker = GENERATED_MARKER,
        state_display = state_display,
        mode = config.mode,
        scope = match config.barrier_scope {
            crate::protocol::BarrierScope::Workspace => "workspace",
            crate::protocol::BarrierScope::Component => "component",
        },
        barrier_timeout = config.barrier_timeout_ms,
        lease_timeout = config.lease_timeout_ms,
        port_base = config.port_base_start,
        port_width = config.port_band_width,
    )
}

/// The one file a developer pastes into a chat window.
///
/// This is deliberately *not* a reference document. It is a bootstrap prompt: it
/// must be short enough to paste, and it must end with an unambiguous first
/// action so the agent starts correctly without a follow-up question. Everything
/// longer lives in `AGENT_INSTRUCTIONS.md`, which this file points at.
fn render_bootstrap_prompt(master: &Path, config: &Config) -> String {
    let state = workspace::state_dir(master);
    format!(
        r#"{marker}
# ScratchPost — Agent Bootstrap

You are reading this because a human attached it to your chat. It is your
onboarding contract for this workspace: read it, then take ownership of the
workspace and follow it for every commit. You do not need to read anything else
first.

---

## You are one of several agents in this workspace

This project is coordinated by **ScratchPost** (`sp`). Other AI agents may be
committing to it at the same time. ScratchPost gives you a private worktree, a
private port band, and a **commit gate** that stops you from silently corrupting
shared state.

The full contract is `AGENT_INSTRUCTIONS.md` in this directory. Read it if you
need detail. This file is enough to start.

## Your first action

Attach to a session. Pick a name that identifies you and is unlikely to collide:

```sh
sp run --agent <your-agent-name> -- bash
```

That command drops you into an isolated workspace at
`{state_display}/sessions/<your-agent-name>/workspace/` with `SP_AGENT`,
`SP_SESSION_ROOT`, `SP_PORT_BASE`, `SERVER_PORT`, `COMPOSE_PROJECT_NAME`, and
`TMPDIR` exported. **Work only there.** Never edit the canonical master folder.

If your harness speaks MCP instead of shell, run `sp --mcp` and call `sp_status`
first. The tools return the same contracts as the CLI.

## The five rules

1. **Stay in your session workspace.** `SP_PATH_OUTSIDE_SESSION` means you left it.
2. **Never invent a migration sequence number.** Before adding a Liquibase
   `<changeSet id>` or a Flyway `V<n>__*.sql`, ask the daemon:
   `sp sequence next --namespace <repo>:<path> --after <n>`
   Use exactly the key it returns.
3. **A blocked commit is not a Git error.** Exit code `1` with `SP_BLOCKED v1` on
   stderr means retrying unchanged will fail again. Parse the final
   `SP_CONFLICT_JSON={{...}}` line and follow `resolution.steps[].command`.
4. **Never use `git commit --no-verify`.** The managed hook rejects it.
5. **Never edit `.scratchpost/`.** That state belongs to the daemon.

## When `git commit` is blocked

You will see this on stderr:

```
SP_BLOCKED v1 code=SP_SEQUENCE_COLLISION conflict_id=...
EVIDENCE
  requested value: 200
  reserved by: agent_1 (intent/claim 1)
  lowest_free: 201
RESOLUTION
  1. ...
       sp resequence --agent <you> --file <repo>/<path> --from 200 --to 201
  2. ...
  3. ...
SP_CONFLICT_JSON={{"schema":"sp.conflict.v1", ...}}
```

Do this, in order:

1. Parse `SP_CONFLICT_JSON`. Do not scrape the prose.
2. Run each `resolution.steps[].command` in order. They are exact and
   copy-pasteable.
3. Re-run your original `git commit` unchanged. It is idempotent and validated
   automatically.

| `code` | What it means | What to do |
|---|---|---|
| `SP_SEQUENCE_COLLISION` | another agent owns this key | run the `sp resequence` step |
| `SP_BARRIER_WAIT` | a barrier is open | wait, then retry |
| `SP_STALE_BASE` | your branch is behind | `sp sync --rebase --agent $SP_AGENT` |
| `SP_INTENT_CONFLICT` | a peer holds a conflicting intent | `sp status`, then retry |
| `SP_SESSION_NOT_ATTACHED` | your lease expired | re-attach with `sp run` |

## Ports

Use `SP_PORT_BASE` / `SERVER_PORT` from your environment. Never bind a literal
port: another agent owns it. Use `COMPOSE_PROJECT_NAME` for Docker Compose.

## Current configuration

| Setting | Value |
|---|---|
| coordination mode | `{mode}` |
| barrier scope | `{scope}` |

## What ScratchPost is doing while you work

`RUNNING_REPORT.md` in this directory is a live audit ledger. The daemon appends
to it whenever it provisions a worktree, allocates a port band, blocks a
collision, or releases a barrier. Read it if you want to know what happened
before you arrived.
"#,
        marker = GENERATED_MARKER,
        state_display = state.to_string_lossy(),
        mode = config.mode,
        scope = match config.barrier_scope {
            crate::protocol::BarrierScope::Workspace => "workspace",
            crate::protocol::BarrierScope::Component => "component",
        },
    )
}

/// Cursor reads `.cursorrules` from the project root. Keep it short: Cursor
/// prepends it to every request, so it must be the highest-signal subset.
fn render_cursorrules(config: &Config) -> String {
    format!(
        r#"{marker}
# ScratchPost coordination rules

This workspace is coordinated by ScratchPost (`sp`). Multiple AI agents may be
active at once. Full contract: `AGENT_INSTRUCTIONS.md`.

## Hard rules

1. **Work only inside your session workspace.** Your `cwd` is
   `.scratchpost/sessions/<agent>/workspace/`. Never edit the canonical master
   folder. `SP_PATH_OUTSIDE_SESSION` means you left it.
2. **Never invent a migration sequence number.** Before adding a Liquibase
   `<changeSet id>` or a Flyway `V<n>__*.sql`, run:
   `sp sequence next --namespace <repo>:<path> --after <n>` and use the result.
3. **A blocked commit is a coordination conflict, not a Git error.** Exit code
   `1` with `SP_BLOCKED v1` on stderr means retrying unchanged will fail again.
   Parse the final `SP_CONFLICT_JSON={{...}}` line and follow
   `resolution.steps[].command`.
4. **Never use `git commit --no-verify`.** The managed hook rejects it.
5. **Never edit `.scratchpost/`.** That state belongs to the daemon.

## Recovery commands

```sh
sp resequence --agent "$SP_AGENT" --file <repo>/<path> --from <old> --to <new>
sp sync --rebase --agent "$SP_AGENT"
sp status --json
sp barrier status
```

## Ports

Use `SP_PORT_BASE` / `SERVER_PORT` from your environment. Do not bind a literal
port; another agent owns it. Use `COMPOSE_PROJECT_NAME` for Docker Compose.

## Mode

Current coordination mode: `{mode}` (barrier scope `{scope}`).
"#,
        marker = GENERATED_MARKER,
        mode = config.mode,
        scope = match config.barrier_scope {
            crate::protocol::BarrierScope::Workspace => "workspace",
            crate::protocol::BarrierScope::Component => "component",
        },
    )
}

/// GitHub Copilot Workspace / Copilot code review reads this file.
fn render_copilot_instructions(config: &Config) -> String {
    format!(
        r#"{marker}
# Copilot instructions for this workspace

This repository is a **ScratchPost-coordinated multi-agent workspace**. Several
coding agents may be editing it concurrently. ScratchPost (`sp`) provides
isolated worktrees, deterministic migration sequence allocation, and a commit
gate. The authoritative contract is `AGENT_INSTRUCTIONS.md`.

## Before you propose a change

- Confirm you are inside a session workspace
  (`.scratchpost/sessions/<agent>/workspace/`). Do not modify the canonical
  master folder.
- If your change adds a database migration, allocate the sequence key first:
  `sp sequence next --namespace <repo>:<path> --after <n>`.
  Liquibase `changeSet id` values and Flyway `V<n>__` prefixes are global
  sequences shared by every agent.
- If your change touches a file another agent has claimed, `sp status --json`
  lists the claims and conflict components.

## When a commit is blocked

`git commit` exits `1` and prints `SP_BLOCKED v1 code=<CODE>` followed by an
`EVIDENCE` block, a `RESOLUTION` block with exact commands, and a final
`SP_CONFLICT_JSON={{...}}` line. Treat this as a coordination conflict:

1. Read `SP_CONFLICT_JSON`. Do not retry the identical commit.
2. Run the commands in `resolution.steps[].command` in order.
3. Re-run the original commit. It is idempotent and validated automatically.

Never use `git commit --no-verify`, never edit `.scratchpost/`, and never
force-push another agent's branch.

## Ports and caches

Use `SP_PORT_BASE`, `SERVER_PORT`, `COMPOSE_PROJECT_NAME`, and `TMPDIR` from the
environment. They are reserved per agent; a literal port will collide.

## Current configuration

- coordination mode: `{mode}`
- barrier scope: `{scope}`
"#,
        marker = GENERATED_MARKER,
        mode = config.mode,
        scope = match config.barrier_scope {
            crate::protocol::BarrierScope::Workspace => "workspace",
            crate::protocol::BarrierScope::Component => "component",
        },
    )
}

/// Claude Code discovers skills under `.claude/skills/<name>/SKILL.md`.
fn render_claude_skill(config: &Config) -> String {
    format!(
        r#"---
name: scratchpost
description: Coordinate with other AI agents in this ScratchPost workspace. Use when committing, adding a database migration (Liquibase changeSet id or Flyway V<n>__ filename), running tests that bind ports, or when a git command fails with SP_BLOCKED.
---

{marker}
# ScratchPost coordination skill

This workspace runs `scratchpostd`, a coordination daemon for parallel coding
agents. It gives every agent a private worktree and port band, allocates
migration sequence keys deterministically, and gates `git commit`.

## When to use this skill

- You are about to `git commit`.
- You are about to add a Liquibase `<changeSet id="...">` or a Flyway
  `V<n>__*.sql` migration.
- You are about to run a test suite or start a server that binds a port.
- A `git` command failed with `SP_BLOCKED`.

## Procedure

1. **Check state.** `sp status --json` returns sessions, claims, open barriers,
   and conflict components. `sp notices --json` returns unread coordination
   notices.
2. **Allocate a sequence key** before writing a migration:
   `sp sequence next --namespace <repo>:<path> --after <n>`.
   The namespace is `<repo>:<file>` for Liquibase and `<repo>:<directory>` for
   Flyway.
3. **Reserve a path** if you are about to edit a file another agent may touch:
   `sp claim --repo <repo> --path <path> --strength advisory`.
4. **Commit normally.** The managed `git` shim validates the staged index against
   the base branch and active claims.
5. **On `SP_BLOCKED`**, parse the final `SP_CONFLICT_JSON={{...}}` line and run the
   commands in `resolution.steps[].command`. Then retry the original commit.
6. **In barrier modes**, call `sp barrier arrive --agent "$SP_AGENT"` when your
   work is complete so peers can proceed.

## MCP alternative

If MCP is available, run `sp --mcp` and use `sp_status`, `sp_claim`,
`sp_sequence_next`, `sp_resequence`, `sp_sync`, and `sp_barrier_arrive` instead
of the CLI. Errors carry the same `SP_BLOCKED` payload with `isError: true`.

## Never

- `git commit --no-verify`
- edit `.scratchpost/`
- force-push another agent's branch
- reuse a sequence key you were not allocated

## Current configuration

- coordination mode: `{mode}`
- barrier scope: `{scope}`
"#,
        marker = GENERATED_MARKER,
        mode = config.mode,
        scope = match config.barrier_scope {
            crate::protocol::BarrierScope::Workspace => "workspace",
            crate::protocol::BarrierScope::Component => "component",
        },
    )
}

fn render_claude_skill_manifest() -> String {
    format!(
        r#"{{
  "name": "scratchpost",
  "version": "{}",
  "description": "Coordinate with parallel AI agents in a ScratchPost workspace: sequence allocation, commit gating, barrier synchronization.",
  "entrypoint": "SKILL.md",
  "tools": [
    "sp_status",
    "sp_claim",
    "sp_sequence_next",
    "sp_resequence",
    "sp_sync",
    "sp_barrier_arrive",
    "sp_notices",
    "sp_config_set",
    "sp_evict"
  ],
  "mcp": {{"command": "sp", "args": ["--mcp"]}},
  "generated_by": "scratchpost"
}}
"#,
        env!("CARGO_PKG_VERSION")
    )
}

/// True when a file was produced by this module. JSON manifests cannot carry an
/// HTML comment, so they are recognised by their `generated_by` field instead.
fn is_generated(content: &str) -> bool {
    content.contains(GENERATED_MARKER) || content.contains("\"generated_by\": \"scratchpost\"")
}

/// Writes every harness scaffold. Files that exist without the generated marker
/// are left untouched and reported in `skipped`.
pub fn write_scaffolds(master: &Path, config: &Config) -> std::io::Result<ScaffoldReport> {
    let instructions = render_instructions(master, config);
    let files: Vec<(&str, String)> = vec![
        (
            "scratchpost-agent-prompt.md",
            render_bootstrap_prompt(master, config),
        ),
        ("AGENT_INSTRUCTIONS.md", instructions.clone()),
        (".scratchpost/agent-instructions.md", instructions),
        (".cursorrules", render_cursorrules(config)),
        (
            ".github/copilot-instructions.md",
            render_copilot_instructions(config),
        ),
        (
            ".claude/skills/scratchpost/SKILL.md",
            render_claude_skill(config),
        ),
        (
            ".claude/skills/scratchpost/skill.json",
            render_claude_skill_manifest(),
        ),
    ];

    debug_assert_eq!(
        files.iter().map(|(name, _)| *name).collect::<Vec<_>>(),
        SCAFFOLD_PATHS.to_vec(),
        "SCAFFOLD_PATHS must list every generated file in order"
    );

    let mut report = ScaffoldReport {
        written: Vec::new(),
        skipped: Vec::new(),
    };
    for (relative, content) in files {
        let path = master.join(relative);
        if let Ok(existing) = fs::read_to_string(&path) {
            if !is_generated(&existing) {
                report.skipped.push(path);
                continue;
            }
        }
        workspace::atomic_write(&path, content.as_bytes())?;
        report.written.push(path);
    }
    Ok(report)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config() -> Config {
        Config::default()
    }

    #[test]
    fn instructions_cover_the_blocked_contract() {
        let text = render_instructions(Path::new("/tmp/sp-test"), &config());
        assert!(text.contains("SP_BLOCKED v1 code="));
        assert!(text.contains("SP_CONFLICT_JSON"));
        assert!(text.contains("sp resequence"));
        assert!(text.contains("sp sync --rebase"));
        assert!(text.contains("sp sequence next"));
        assert!(text.contains("sp --mcp"));
        assert!(text.starts_with(GENERATED_MARKER));
    }

    #[test]
    fn bootstrap_prompt_is_pasteable_and_actionable() {
        let text = render_bootstrap_prompt(Path::new("/tmp/sp-test"), &config());
        assert!(text.starts_with(GENERATED_MARKER));
        // It must tell the agent how to attach before anything else.
        assert!(text.contains("sp run --agent"));
        // It must carry the blocked contract, not just point at another file.
        assert!(text.contains("SP_BLOCKED v1"));
        assert!(text.contains("SP_CONFLICT_JSON"));
        assert!(text.contains("sp resequence"));
        assert!(text.contains("sp sequence next"));
        assert!(text.contains("sp --mcp"));
        // It must point at the audit ledger.
        assert!(text.contains("RUNNING_REPORT.md"));
        // Short enough to paste into a chat window.
        assert!(
            text.lines().count() < 130,
            "bootstrap prompt is too long to paste"
        );
    }

    #[test]
    fn every_scaffold_carries_the_marker() {
        let cfg = config();
        for text in [
            render_bootstrap_prompt(Path::new("/tmp/sp-test"), &cfg),
            render_cursorrules(&cfg),
            render_copilot_instructions(&cfg),
            render_claude_skill(&cfg),
        ] {
            assert!(text.contains(GENERATED_MARKER), "missing marker");
        }
        let manifest = render_claude_skill_manifest();
        assert!(manifest.contains("\"name\": \"scratchpost\""));
        assert!(manifest.contains("\"--mcp\""));
    }

    #[test]
    fn scaffolds_are_written_and_user_files_preserved() {
        let root = std::env::temp_dir().join(format!("sp-agents-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        fs::write(root.join(".cursorrules"), "hand written\n").unwrap();

        let report = write_scaffolds(&root, &config()).unwrap();
        assert!(report.skipped.iter().any(|p| p.ends_with(".cursorrules")));
        assert_eq!(
            fs::read_to_string(root.join(".cursorrules")).unwrap(),
            "hand written\n"
        );
        assert!(root.join("scratchpost-agent-prompt.md").exists());
        assert!(root.join("AGENT_INSTRUCTIONS.md").exists());
        assert!(root.join(".github/copilot-instructions.md").exists());
        assert!(root.join(".claude/skills/scratchpost/SKILL.md").exists());

        // A second run is idempotent: it rewrites its own files and keeps
        // skipping the user-owned one.
        let second = write_scaffolds(&root, &config()).unwrap();
        assert_eq!(second.skipped.len(), 1);
        assert!(second.skipped[0].ends_with(".cursorrules"));
        assert_eq!(second.written.len(), SCAFFOLD_PATHS.len() - 1);
        let _ = fs::remove_dir_all(&root);
    }
}
